export const emptyState = () => ({version:1, answers:[], bookmarks:[], session:null});
export function shuffle(items, random=Math.random){const result=[...items];for(let i=result.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[result[i],result[j]]=[result[j],result[i]];}return result;}
export function latestAnswers(answers){return new Map(answers.map(a=>[a.id,a]));}
export function filterQuestions(bank,state,category,mode){const latest=latestAnswers(state.answers);return bank.filter(q=>(category==='all'||q.category===category)&&(mode==='all'||mode==='unseen'&&!latest.has(q.id)||mode==='weak'&&latest.get(q.id)?.correct===false||mode==='bookmarks'&&state.bookmarks.includes(q.id)));}
export function validateBank(bank){if(!Array.isArray(bank)||!bank.length)throw Error('問題集が空です');const ids=new Set();for(const q of bank){if(!q.id||ids.has(q.id)||!q.category||!q.prompt||!q.explanation||!Array.isArray(q.choices)||q.choices.length!==4||q.choices.some(c=>typeof c!=='string'||!c.trim())||new Set(q.choices).size!==4||!Number.isInteger(q.answer)||q.answer<0||q.answer>3)throw Error(`問題の形式を確認してください: ${q.id}`);ids.add(q.id);}return bank;}
export function validateState(data,bank){const ids=new Set(bank.map(q=>q.id));if(data?.version!==1||!Array.isArray(data.answers)||!Array.isArray(data.bookmarks)||data.answers.length>100000)throw Error('履歴ファイルの形式が違います');if(data.answers.some(a=>!a||typeof a.id!=='string'||typeof a.correct!=='boolean'||!Number.isInteger(a.choice)||a.choice<0||a.choice>3||typeof a.at!=='string'||!Number.isFinite(Date.parse(a.at))))throw Error('回答履歴が不正です');if(data.bookmarks.some(id=>typeof id!=='string'))throw Error('お気に入りが不正です');return {version:1,answers:data.answers.filter(a=>ids.has(a.id)).map(a=>({id:a.id,choice:a.choice,correct:a.correct,at:a.at})),bookmarks:[...new Set(data.bookmarks.filter(id=>ids.has(id)))],session:null};}
